"    if (clearData) {
      // Check for active carts or busy tables first (ignore pre-orders)
      const hasActiveCarts = 
        (dineInCart && dineInCart.length > 0) ||
        (pickupCart && pickupCart.length > 0) ||
        (quickCart && quickCart.length > 0) ||
        (preOrderCart && preOrderCart.length > 0) ||
        Object.entries(tableCarts || {}).some(([tableId, c]) => {
          if (String(tableId).startsWith('temp-')) return false;
          return Array.isArray(c) && c.length > 0;
        });

      const hasBusyTables = Object.entries(tableStatuses || {}).some(([tableId, status]) => {
        if (String(tableId).startsWith('temp-')) return false;
        return status === 'SAVED' || status === 'BILL_SAVED' || status === 'PRINTED';
      });

      if (hasActiveCarts || hasBusyTables) {
        toast.error("Data can't be cleared: Tables are busy.");
        return;
      }"
